//! AVR LLIL lifter ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â supports the AVR 8-bit microcontroller ISA.
//!
//! This lifter is mnemonic-driven: it parses the `mnemonic` string and the
//! structured `operand_list` (falling back to the raw `operands` text) from
//! the [`Instruction`] struct.  It does **not** decode raw bytes, which keeps
//! it independent of any particular AVR disassembler front-end.
//!
//! # Architecture overview
//!
//! AVR is an 8-bit RISC microcontroller with the following key features:
//!
//! - **32 general-purpose 8-bit registers**: `r0`ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œ`r31`.
//! - **Three 16-bit pointer registers** formed from register pairs:
//!   - X = `r26`:`r27` (XL:XH)
//!   - Y = `r28`:`r29` (YL:YH)
//!   - Z = `r30`:`r31` (ZL:ZH)
//! - **Stack pointer**: `SP` = `SPH`:`SPL` (16-bit, in I/O space).
//! - **Status register**: `SREG` with bits I, T, H, S, V, N, Z, C.
//! - **Program memory** is word-addressed (each address = 2 bytes).
//! - **Data memory** (SRAM) is byte-addressed; I/O registers occupy `0x20`ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œ`0x5F`.
//!
//! # Operand conventions
//!
//! AVR disassemblers (avr-objdump, avr-as, LLVM) write operands as:
//! - Register names: `r0`ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œ`r31`, `X`, `Y`, `Z`, `X+`, `-X`, `Y+`, `-Y`, etc.
//! - Immediates: decimal or `0x`-prefixed hex.
//! - Indirect load/store modes: `X`, `X+`, `-X`, `Y+q`, `-Y`, `Z+`, `-Z`, `Z+q`.
//!
//! The lifter normalises register names and uses [`IrExpr::Intrinsic`] for
//! side-effects it cannot represent with the core IR (flag writes, nibble
//! swaps, I/O port access, etc.).

use super::{ArchLifter, Effect, IrExpr, LiftError, LiftLevel, LiftedInstr};
use rustre_core::arch::Instruction;
use std::fmt;

