    fn lift_add(ops: &[&str]) -> Vec<Effect> {
        Self::lift_arith2(ops, |a, b| IrExpr::Add(Box::new(a), Box::new(b)))
    }

    /// ADC rd, rs ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â rd = rd + rs + C (carry modelled as Intrinsic arg)
    fn lift_adc(ops: &[&str]) -> Vec<Effect> {
        if ops.len() < 2 {
            return vec![Effect::Intrinsic {
                name: "adc_bad_ops".into(),
                args: vec![],
            }];
        }
        let rd = Self::norm_reg(ops[0]);
        let rs = Self::reg_expr(ops[1]);
        let lhs = IrExpr::Reg(rd.clone());
        let sum = IrExpr::Add(Box::new(lhs), Box::new(rs));
        let carry = IrExpr::Reg("sreg_c".to_string());
        vec![Effect::RegWrite {
            reg: rd,
            value: IrExpr::Add(Box::new(sum), Box::new(carry)),
        }]
    }

    /// ADIW Rd+1:Rd, K ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â 16-bit add of 6-bit immediate to word register pair.
    ///
    /// Rd must be r24, r26, r28, or r30.
    fn lift_adiw(ops: &[&str]) -> Vec<Effect> {
        if ops.len() < 2 {
            return vec![Effect::Intrinsic {
                name: "adiw_bad_ops".into(),
                args: vec![],
            }];
        }
        // ops[0] is the low register of the pair (r24, r26, r28, or r30)
        let rd_low = Self::norm_reg(ops[0]);
        let k = IrExpr::Const(Self::parse_imm(ops[1]).unwrap_or(0).cast_unsigned());
        let rd_n: u32 = rd_low.trim_start_matches('r').parse().unwrap_or(24);
        let rd_high = format!("r{}", rd_n + 1);

        // word = (rH << 8 | rL) + K; rL = word & 0xFF; rH = (word >> 8) & 0xFF
        let pair = Self::word_pair(&rd_low);
        let result = IrExpr::Add(Box::new(pair), Box::new(k));
        vec![
            Effect::RegWrite {
                reg: rd_low,
                value: IrExpr::And(Box::new(result.clone()), Box::new(IrExpr::Const(0xFF))),
            },
            Effect::RegWrite {
                reg: rd_high,
                value: IrExpr::And(
                    Box::new(IrExpr::Shr(Box::new(result), Box::new(IrExpr::Const(8)))),
                    Box::new(IrExpr::Const(0xFF)),
                ),
            },
        ]
    }

    /// SUB rd, rs ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â rd = rd - rs
    fn lift_sub(ops: &[&str]) -> Vec<Effect> {
        Self::lift_arith2(ops, |a, b| IrExpr::Sub(Box::new(a), Box::new(b)))
    }

    /// SBC rd, rs ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â rd = rd - rs - C
    fn lift_sbc(ops: &[&str]) -> Vec<Effect> {
        if ops.len() < 2 {
            return vec![Effect::Intrinsic {
                name: "sbc_bad_ops".into(),
                args: vec![],
            }];
        }
        let rd = Self::norm_reg(ops[0]);
        let rs = Self::reg_expr(ops[1]);
        let lhs = IrExpr::Reg(rd.clone());
        let diff = IrExpr::Sub(Box::new(lhs), Box::new(rs));
        let carry = IrExpr::Reg("sreg_c".to_string());
        vec![Effect::RegWrite {
            reg: rd,
            value: IrExpr::Sub(Box::new(diff), Box::new(carry)),
        }]
    }

    /// SUBI rd, K ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â rd = rd - K  (only r16ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œr31)
    fn lift_subi(ops: &[&str]) -> Vec<Effect> {
        Self::lift_arith_imm(ops, |a, b| IrExpr::Sub(Box::new(a), Box::new(b)))
    }

    /// SBCI rd, K ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â rd = rd - K - C
    fn lift_sbci(ops: &[&str]) -> Vec<Effect> {
        if ops.len() < 2 {
            return vec![Effect::Intrinsic {
                name: "sbci_bad_ops".into(),
                args: vec![],
            }];
        }
        let rd = Self::norm_reg(ops[0]);
        let k = IrExpr::Const(Self::parse_imm(ops[1]).unwrap_or(0).cast_unsigned());
        let lhs = IrExpr::Reg(rd.clone());
        let carry = IrExpr::Reg("sreg_c".to_string());
        let diff = IrExpr::Sub(Box::new(lhs), Box::new(k));
        vec![Effect::RegWrite {
            reg: rd,
            value: IrExpr::Sub(Box::new(diff), Box::new(carry)),
        }]
    }

    /// SBIW Rd+1:Rd, K ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â 16-bit subtract of 6-bit immediate from word reg pair.
    fn lift_sbiw(ops: &[&str]) -> Vec<Effect> {
        if ops.len() < 2 {
            return vec![Effect::Intrinsic {
                name: "sbiw_bad_ops".into(),
                args: vec![],
            }];
        }
        let rd_low = Self::norm_reg(ops[0]);
        let k = IrExpr::Const(Self::parse_imm(ops[1]).unwrap_or(0).cast_unsigned());
        let rd_n: u32 = rd_low.trim_start_matches('r').parse().unwrap_or(24);
        let rd_high = format!("r{}", rd_n + 1);

        let pair = Self::word_pair(&rd_low);
        let result = IrExpr::Sub(Box::new(pair), Box::new(k));
        vec![
            Effect::RegWrite {
                reg: rd_low,
                value: IrExpr::And(Box::new(result.clone()), Box::new(IrExpr::Const(0xFF))),
            },
            Effect::RegWrite {
                reg: rd_high,
                value: IrExpr::And(
                    Box::new(IrExpr::Shr(Box::new(result), Box::new(IrExpr::Const(8)))),
                    Box::new(IrExpr::Const(0xFF)),
                ),
            },
        ]
    }

    /// AND rd, rs
    fn lift_and(ops: &[&str]) -> Vec<Effect> {
        Self::lift_arith2(ops, |a, b| IrExpr::And(Box::new(a), Box::new(b)))
    }

    /// ANDI rd, K
    fn lift_andi(ops: &[&str]) -> Vec<Effect> {
        Self::lift_arith_imm(ops, |a, b| IrExpr::And(Box::new(a), Box::new(b)))
    }

