/// Decoded pointer-register addressing mode for AVR LD/ST instructions.
#[derive(Debug, Clone)]
struct PtrMode {
    /// Low byte of the pointer register pair (e.g. `"r26"` for X).
    base: &'static str,
    /// True if the pointer is pre-decremented before the access.
    pre_dec: bool,
    /// True if the pointer is post-incremented after the access.
    post_inc: bool,
    /// Constant displacement (0ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œ63, used in `Y+q` / `Z+q` modes).
    disp: u64,
}

