    #[test]
    fn add_r1_r2() {
        let li = lift("add", "r1, r2");
        assert!(has_reg_write(&li, "r1"));
        let val = reg_write_value(&li, "r1").unwrap();
        assert!(
            matches!(val, IrExpr::Add(..)),
            "ADD should produce an Add node, got: {val:?}"
        );
    }

    #[test]
    fn add_writes_destination_register() {
        let li = lift("add", "r5, r6");
        assert!(has_reg_write(&li, "r5"), "ADD should write to r5");
    }

    #[test]
    fn adc_produces_add_with_carry() {
        let li = lift("adc", "r3, r4");
        assert!(has_reg_write(&li, "r3"));
        // The value should contain a reference to sreg_c
        let val = reg_write_value(&li, "r3").unwrap();
        let uses_carry = val.registers_used().contains(&"sreg_c".to_string());
        assert!(uses_carry, "ADC should reference sreg_c carry flag");
    }

