    #[test]
    fn sub_r1_r2() {
        let li = lift("sub", "r1, r2");
        assert!(has_reg_write(&li, "r1"));
        let val = reg_write_value(&li, "r1").unwrap();
        assert!(
            matches!(val, IrExpr::Sub(..)),
            "SUB should produce a Sub node, got: {val:?}"
        );
    }

    #[test]
    fn subi_r20_5() {
        let li = lift("subi", "r20, 5");
        assert!(has_reg_write(&li, "r20"));
        let val = reg_write_value(&li, "r20").unwrap();
        assert!(matches!(val, IrExpr::Sub(..)));
    }

