    #[test]
    fn and_r0_r1() {
        let li = lift("and", "r0, r1");
        assert!(has_reg_write(&li, "r0"));
        let val = reg_write_value(&li, "r0").unwrap();
        assert!(matches!(val, IrExpr::And(..)));
    }

    #[test]
    fn andi_r16_0xf0() {
        let li = lift("andi", "r16, 0xf0");
        assert!(has_reg_write(&li, "r16"));
    }

    #[test]
    fn or_r2_r3() {
        let li = lift("or", "r2, r3");
        assert!(has_reg_write(&li, "r2"));
        let val = reg_write_value(&li, "r2").unwrap();
        assert!(matches!(val, IrExpr::Or(..)));
    }

    #[test]
    fn eor_r7_r7_is_clr() {
        let li = lift("eor", "r7, r7");
        assert!(has_reg_write(&li, "r7"));
        let val = reg_write_value(&li, "r7").unwrap();
        assert!(matches!(val, IrExpr::Xor(..)));
    }

    #[test]
    fn com_r5() {
        // COM rd = 0xFF - rd
        let li = lift("com", "r5");
        assert!(has_reg_write(&li, "r5"));
        let val = reg_write_value(&li, "r5").unwrap();
        // IrExpr::Sub(Const(0xFF), _)
        if let IrExpr::Sub(lhs, _) = val {
            assert_eq!(**lhs, IrExpr::Const(0xFF), "COM lhs should be 0xFF");
        } else {
            panic!("COM should produce Sub, got {val:?}");
        }
    }

    #[test]
    fn neg_r8() {
        let li = lift("neg", "r8");
        assert!(has_reg_write(&li, "r8"));
        let val = reg_write_value(&li, "r8").unwrap();
        if let IrExpr::Sub(lhs, _) = val {
            assert_eq!(**lhs, IrExpr::Const(0), "NEG lhs should be 0");
        } else {
            panic!("NEG should produce Sub(0, rd), got {val:?}");
        }
    }

