    #[test]
    fn mov_r0_r1() {
        let li = lift("mov", "r0, r1");
        assert!(has_reg_write(&li, "r0"));
        let val = reg_write_value(&li, "r0").unwrap();
        assert_eq!(*val, IrExpr::Reg("r1".to_string()));
    }

    #[test]
    fn movw_r24_r22() {
        let li = lift("movw", "r24, r22");
        // Should write both r24 (low) and r25 (high)
        assert!(has_reg_write(&li, "r24"), "MOVW should write r24");
        assert!(
            has_reg_write(&li, "r25"),
            "MOVW should write r25 (high byte)"
        );
    }

