    #[test]
    fn ld_r0_x() {
        let li = lift("ld", "r0, X");
        let has_mem_read = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::MemRead { dest, .. } if dest == "r0"));
        assert!(has_mem_read, "LD r0, X should produce a MemRead into r0");
    }

    #[test]
    fn ld_r1_x_post_increment() {
        let li = lift("ld", "r1, X+");
        // Should have a MemRead and a RegWrite for post-increment
        let has_read = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::MemRead { dest, .. } if dest == "r1"));
        let has_inc = li.effects.iter().any(|e| matches!(e, Effect::RegWrite { reg, value: IrExpr::And(..) } if reg == "r26" || reg == "r27"));
        assert!(has_read, "LD r1, X+ should read memory");
        assert!(has_inc, "LD r1, X+ should increment X (r26/r27)");
    }

    #[test]
    fn ld_r2_pre_dec_y() {
        let li = lift("ld", "r2, -Y");
        // Should have pre-dec writes and a MemRead
        let has_read = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::MemRead { dest, .. } if dest == "r2"));
        assert!(has_read, "LD r2, -Y should read memory into r2");
    }

    #[test]
    fn lds_r3_sram_addr() {
        let li = lift("lds", "r3, 0x0100");
        let has_read = li.effects.iter().any(|e| {
            matches!(e, Effect::MemRead { addr: IrExpr::Const(0x100), dest, .. } if dest == "r3")
        });
        assert!(has_read, "LDS should read from absolute address 0x100");
    }

