    #[test]
    fn push_r0() {
        let li = lift("push", "r0");
        let has_write = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::MemWrite { .. }));
        let has_sp_dec = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::RegWrite { reg, value: IrExpr::Sub(..) } if reg == "spl"));
        assert!(has_write, "PUSH should write to memory");
        assert!(has_sp_dec, "PUSH should decrement SP");
    }

    #[test]
    fn pop_r1() {
        let li = lift("pop", "r1");
        let has_read = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::MemRead { dest, .. } if dest == "r1"));
        let has_sp_inc = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::RegWrite { reg, value: IrExpr::Add(..) } if reg == "spl"));
        assert!(has_read, "POP should read from memory into r1");
        assert!(has_sp_inc, "POP should increment SP");
    }

