    #[test]
    fn rjmp_produces_unconditional_branch() {
        let lifter = AvrLifter::new();
        let mut instr = make_instr(0x200, "rjmp", "0x400");
        instr.size = 2;
        let li = lifter.lift(&instr).unwrap();
        let has_branch = li.effects.iter().any(|e| {
            matches!(
                e,
                Effect::Branch {
                    condition: None,
                    ..
                }
            )
        });
        assert!(has_branch, "RJMP should produce an unconditional Branch");
        assert!(li.is_terminator(), "RJMP should be a terminator");
    }

    #[test]
    fn ijmp_indirect_via_z() {
        let li = lift("ijmp", "");
        let has_branch = li.effects.iter().any(|e| {
            matches!(
                e,
                Effect::Branch {
                    condition: None,
                    ..
                }
            )
        });
        assert!(has_branch, "IJMP should produce an unconditional Branch");
    }

    #[test]
    fn ret_produces_return() {
        let li = lift("ret", "");
        let has_return = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::Return { value: None }));
        assert!(has_return, "RET should produce a Return effect");
        assert!(li.is_terminator(), "RET should be a terminator");
    }

    #[test]
    fn reti_produces_return_and_enables_interrupts() {
        let li = lift("reti", "");
        let has_return = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::Return { .. }));
        let has_sei = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::Intrinsic { name, .. } if name == "avr_sei"));
        assert!(has_return, "RETI should produce a Return");
        assert!(has_sei, "RETI should set the I flag");
    }

    #[test]
    fn rcall_produces_call() {
        let lifter = AvrLifter::new();
        let mut instr = make_instr(0x100, "rcall", "0x200");
        instr.size = 2;
        let li = lifter.lift(&instr).unwrap();
        let has_call = li.effects.iter().any(|e| matches!(e, Effect::Call { .. }));
        assert!(has_call, "RCALL should produce a Call effect");
    }

    #[test]
    fn call_absolute_address() {
        let li = lift("call", "0x1000");
        let has_call = li.effects.iter().any(|e| {
            matches!(
                e,
                Effect::Call {
                    target: IrExpr::Const(0x1000)
                }
            )
        });
        assert!(has_call, "CALL should call absolute address 0x1000");
    }

    #[test]
    fn jmp_absolute_address() {
        let li = lift("jmp", "0x2000");
        let has_branch = li.effects.iter().any(|e| {
            matches!(
                e,
                Effect::Branch {
                    target: IrExpr::Const(0x2000),
                    condition: None
                }
            )
        });
        assert!(has_branch, "JMP should branch to 0x2000");
    }

