    #[test]
    fn breq_uses_sreg_z() {
        let li = lift("breq", "0x300");
        let has_cond_branch = li.effects.iter().any(|e| {
            if let Effect::Branch {
                condition: Some(cond),
                ..
            } = e
            {
                cond.registers_used().contains(&"sreg_z".to_string())
            } else {
                false
            }
        });
        assert!(has_cond_branch, "BREQ should branch on sreg_z");
    }

    #[test]
    fn brne_uses_not_sreg_z() {
        let li = lift("brne", "0x300");
        let has_cond_branch = li.effects.iter().any(|e| {
            if let Effect::Branch {
                condition: Some(IrExpr::Not(inner)),
                ..
            } = e
            {
                inner.registers_used().contains(&"sreg_z".to_string())
            } else {
                false
            }
        });
        assert!(has_cond_branch, "BRNE should branch on NOT sreg_z");
    }

    #[test]
    fn brcs_uses_sreg_c() {
        let li = lift("brcs", "0x300");
        let has_c = li.effects.iter().any(|e| {
            if let Effect::Branch {
                condition: Some(cond),
                ..
            } = e
            {
                cond.registers_used().contains(&"sreg_c".to_string())
            } else {
                false
            }
        });
        assert!(has_c, "BRCS should branch on sreg_c");
    }

    #[test]
    fn brge_uses_n_and_v() {
        let li = lift("brge", "0x300");
        let has_nv = li.effects.iter().any(|e| {
            if let Effect::Branch {
                condition: Some(cond),
                ..
            } = e
            {
                let regs = cond.registers_used();
                regs.contains(&"sreg_n".to_string()) && regs.contains(&"sreg_v".to_string())
            } else {
                false
            }
        });
        assert!(has_nv, "BRGE should reference sreg_n and sreg_v");
    }

