    #[test]
    fn cp_produces_intrinsic() {
        let li = lift("cp", "r10, r11");
        let has_intrinsic = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::Intrinsic { name, .. } if name == "avr_cp"));
        assert!(has_intrinsic, "CP should produce avr_cp intrinsic");
    }

    #[test]
    fn cpi_produces_intrinsic_with_const() {
        let li = lift("cpi", "r16, 100");
        let has_intrinsic = li.effects.iter().any(|e| {
            if let Effect::Intrinsic { name, args } = e {
                name == "avr_cpi" && args.contains(&IrExpr::Const(100))
            } else {
                false
            }
        });
        assert!(
            has_intrinsic,
            "CPI should produce avr_cpi with constant 100"
        );
    }

