    #[test]
    fn adiw_r24_6() {
        let li = lift("adiw", "r24, 6");
        // Should write r24 (low) and r25 (high)
        assert!(has_reg_write(&li, "r24"), "ADIW should write r24");
        assert!(has_reg_write(&li, "r25"), "ADIW should write r25");
    }

    #[test]
    fn sbiw_r26_4() {
        let li = lift("sbiw", "r26, 4");
        assert!(has_reg_write(&li, "r26"), "SBIW should write r26");
        assert!(has_reg_write(&li, "r27"), "SBIW should write r27");
    }

