    #[test]
    fn lsl_r0() {
        let li = lift("lsl", "r0");
        assert!(has_reg_write(&li, "r0"));
        let val = reg_write_value(&li, "r0").unwrap();
        if let IrExpr::Shl(_, rhs) = val {
            assert_eq!(**rhs, IrExpr::Const(1), "LSL shift amount should be 1");
        } else {
            panic!("LSL should produce Shl(_,1), got {val:?}");
        }
    }

    #[test]
    fn lsr_r0() {
        let li = lift("lsr", "r0");
        assert!(has_reg_write(&li, "r0"));
        let val = reg_write_value(&li, "r0").unwrap();
        if let IrExpr::Shr(_, rhs) = val {
            assert_eq!(**rhs, IrExpr::Const(1), "LSR shift amount should be 1");
        } else {
            panic!("LSR should produce Shr(_,1), got {val:?}");
        }
    }

