    #[test]
    fn lpm_z_reads_from_z_pointer() {
        let li = lift("lpm", "r0, Z");
        let has_read = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::MemRead { dest, .. } if dest == "r0"));
        assert!(has_read, "LPM r0, Z should produce a MemRead into r0");
    }

