    #[test]
    fn ret_is_terminator() {
        let li = lift("ret", "");
        assert!(li.is_terminator());
    }

    #[test]
    fn rjmp_is_terminator() {
        let li = lift("rjmp", "0x400");
        assert!(li.is_terminator());
    }

    #[test]
    fn breq_is_terminator() {
        let li = lift("breq", "0x300");
        assert!(li.is_terminator());
    }

    #[test]
    fn ldi_is_not_terminator() {
        let li = lift("ldi", "r16, 42");
        assert!(!li.is_terminator());
    }

