    #[test]
    fn address_is_preserved() {
        let lifter = AvrLifter::new();
        let instr = make_instr(0xABCD, "nop", "");
        let li = lifter.lift(&instr).unwrap();
        assert_eq!(li.address, 0xABCD);
    }

