    #[test]
    fn unknown_mnemonic_produces_intrinsic() {
        let li = lift("unknownavrmnemonic", "");
        let has_intrinsic = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::Intrinsic { .. }));
        assert!(
            has_intrinsic,
            "Unknown mnemonic should produce an Intrinsic fallback"
        );
    }

