    #[test]
    fn sbrc_produces_intrinsic() {
        let li = lift("sbrc", "r10, 3");
        assert!(
            li.effects
                .iter()
                .any(|e| matches!(e, Effect::Intrinsic { name, .. } if name == "avr_sbrc"))
        );
    }

