    #[test]
    fn norm_reg_x_variants() {
        assert_eq!(AvrLifter::norm_reg("X"), "r26");
        assert_eq!(AvrLifter::norm_reg("XL"), "r26");
        assert_eq!(AvrLifter::norm_reg("XH"), "r27");
        assert_eq!(AvrLifter::norm_reg("Y"), "r28");
        assert_eq!(AvrLifter::norm_reg("Z"), "r30");
    }

    #[test]
    fn norm_reg_sp() {
        assert_eq!(AvrLifter::norm_reg("SP"), "spl");
        assert_eq!(AvrLifter::norm_reg("SPL"), "spl");
        assert_eq!(AvrLifter::norm_reg("SPH"), "sph");
    }

    #[test]
    fn norm_reg_rn_passthrough() {
        assert_eq!(AvrLifter::norm_reg("r0"), "r0");
        assert_eq!(AvrLifter::norm_reg("r31"), "r31");
    }

