    #[test]
    fn parse_imm_decimal() {
        assert_eq!(AvrLifter::parse_imm("42"), Some(42));
    }

    #[test]
    fn parse_imm_hex() {
        assert_eq!(AvrLifter::parse_imm("0xFF"), Some(255));
    }

    #[test]
    fn parse_imm_negative() {
        assert_eq!(AvrLifter::parse_imm("-1"), Some(-1));
    }

    #[test]
    fn parse_imm_invalid() {
        assert_eq!(AvrLifter::parse_imm("notanumber"), None);
    }

